#include <stdlib.h>

int *make_buffer(int size) {
    if (size <= 0) {
        return NULL;
    }

    int *buffer = malloc(sizeof(int) * (size_t)size);
    if (buffer == NULL) {
        return NULL;
    }

    buffer[0] = 0;
    return buffer;
}

